/// <summary>
///     Data Controller class for <c>AVASalesRouteCardReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Controller class for the <c>AVASalesRouteCardReport</c> SSRS Report.
/// </remarks>
internal final class AVAInventTransferJourController extends  SrsReportRunController
{
    Args                        clsArgs;
    InventTransferJour          clsInventTransferJour;
    InventTransferUpdateType    clsInventTransferUpdateType;
    boolean                     clsPreviewMode;

}

Method.Source:
/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVAInventTransferJourController</c> as return value
/// </returns>
public static AVAInventTransferJourController construct()
{
    return new AVAInventTransferJourController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmInventTransferJour</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>InventTransferJour</c> as type
/// </param>
/// <returns>
///    <c>InventTransferJour</c> as return value
/// </returns>
public InventTransferJour parmInventTransferJour(InventTransferJour _parmValue = clsInventTransferJour)
{
    clsInventTransferJour = _parmValue;

    return clsInventTransferJour;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAInventTransferJourController controller;

    controller = AVAInventTransferJourController::newFromArgs(_args);

    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVAInventTransferJourContract contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();
    contract.parmInventTransferJourRefRecId(clsInventTransferJour.RecId);
    contract.parmTransferId(clsInventTransferJour.TransferId);
    contract.parmVoucherId(clsInventTransferJour.VoucherId);
    contract.parmTransDate(clsInventTransferJour.TransDate);
    contract.parmUpdateType(clsInventTransferJour.UpdateType);

    clsPreviewMode = true;
    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName() == menuItemActionStr(AVAInventTransferJourActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName() == menuItemActionStr(AVAInventTransferJourAction))
        {
            clsPreviewMode = false;
        }
        else if(this.parmArgs().menuItemName() == menuItemOutputStr(AVAInventTransferJourShipOutput))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVAInventTransferJourController</c> as return value
/// </returns>
public static AVAInventTransferJourController newFromArgs(Args _args)
{
    AVAInventTransferJourController locController;
    Common                          locCommon;
    InventTransferJour              locInventTransferJour;
    InventTransferParmTable         locInventTransferParmTable;
    Args                            locArgs;

    //controller = new AVAInventTransferJourController();
    locController = AVAInventTransferJourController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(true);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();
            if(     locCommon.RecId
                &&  locCommon.TableId == tableNum(InventTransferJour))
            {
                locInventTransferJour = locCommon;
                locController.parmInventTransferJour(locInventTransferJour);

                locArgs = new Args();
                locArgs = _args;
                locArgs.parmEnumType(enumNum(InventTransferUpdateType));
                locArgs.parmEnum(locInventTransferJour.UpdateType);
                locArgs.menuItemType(MenuItemType::Output);
                locArgs.menuItemName(menuItemOutputStr(AVAInventTransferJourShipOutput));
                if(locInventTransferJour.UpdateType == InventTransferUpdateType::Shipment)
                {
                    locController.parmArgs(locArgs);
                    locController.parmReportName(ssrsReportStr(AVAInventTransferJour, ReportShip));
                    locController.parmDialogCaption("@SYS10200");
                }
            }
            if(     locCommon.RecId
                &&  locCommon.TableId == tableNum(InventTransferParmTable))
            {
                locInventTransferParmTable = locCommon;
                //ToDo: check way to get correct journal table
                select firstonly locInventTransferJour
                order by locInventTransferJour.RecId desc
                where   locInventTransferJour.UpdateType == InventTransferUpdateType::Shipment
                    &&  locInventTransferJour.TransferId == locInventTransferParmTable.TransferId;
                locController.parmInventTransferJour(locInventTransferJour);

                locArgs = new Args();
                locArgs = _args;
                locArgs.parmEnumType(enumNum(InventTransferUpdateType));
                locArgs.parmEnum(locInventTransferParmTable.UpdateType);
                locArgs.menuItemType(MenuItemType::Output);
                locArgs.menuItemName(menuItemOutputStr(AVAInventTransferJourShipOutput));
                if(locInventTransferParmTable.UpdateType == InventTransferUpdateType::Shipment)
                {
                    locController.parmArgs(locArgs);
                    locController.parmReportName(ssrsReportStr(AVAInventTransferJour, ReportShip));
                    locController.parmDialogCaption("@SYS10200");
                }
            }
        }
    }
    return locController;
}
